using System.Text.Json;
using Lunate.Agent;
using ModelContextProtocol;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;
using LunateAnnotations = Lunate.Agent.ToolAnnotations;
using McpAnnotations = ModelContextProtocol.Protocol.ToolAnnotations;
using McpTool = ModelContextProtocol.Protocol.Tool;

namespace Lunate.Protocols;

/// <summary>
/// One <see cref="ITool"/> served over MCP. The declaration is the tool's hand-written schema —
/// never generated by reflection — and a call runs the tool in-process, mapping its
/// <see cref="ToolResult"/> to a <c>tools/call</c> result. The server exposes no approval seam: only
/// tools whose own contract is read-only belong here.
/// </summary>
internal sealed class McpServerToolAdapter(ITool tool, string workingDirectory) : McpServerTool
{
    private readonly McpTool protocolTool = new()
    {
        Name = tool.Name,
        Description = tool.Description,
        InputSchema = tool.ParametersSchema.Clone(),
        Annotations = MapAnnotations(tool.Annotations),
    };

    public override McpTool ProtocolTool => protocolTool;

    public override IReadOnlyList<object> Metadata => [];

    public override async ValueTask<CallToolResult> InvokeAsync(
        RequestContext<CallToolRequestParams> request,
        CancellationToken cancellationToken = default
    )
    {
        JsonElement args = Arguments(request.Params);
        ToolResult result = await tool.ExecuteAsync(
                args,
                new ToolContext(workingDirectory, NullAgentEvents.Instance),
                cancellationToken
            )
            .ConfigureAwait(false);

        return new CallToolResult
        {
            Content = [new TextContentBlock { Text = result.Output }],
            IsError = result.IsError,
            StructuredContent = result.StructuredContent
                is { ValueKind: JsonValueKind.Object } value
                ? value.Clone()
                : null,
        };
    }

    private static JsonElement Arguments(CallToolRequestParams? parameters) =>
        parameters?.Arguments is { Count: > 0 } arguments
            ? JsonSerializer.SerializeToElement(arguments, McpJsonUtilities.DefaultOptions)
            : JsonDocument.Parse("{}").RootElement.Clone();

    private static McpAnnotations? MapAnnotations(LunateAnnotations? annotations) =>
        annotations is null
            ? null
            : new McpAnnotations
            {
                ReadOnlyHint = annotations.ReadOnly,
                DestructiveHint = annotations.Destructive,
                IdempotentHint = annotations.Idempotent,
                OpenWorldHint = annotations.OpenWorld,
            };

    /// <summary>The tools emit no events here; the server has no run to report them to.</summary>
    private sealed class NullAgentEvents : IAgentEvents
    {
        internal static NullAgentEvents Instance { get; } = new();

        public void Emit(AgentEvent agentEvent) { }
    }
}
